package com.smartlibrary.algorithms.string;import java.util.*;
public final class RabinKarp {private RabinKarp(){}public record Result(List<Integer> positions,long hashChecks,long charComparisons){}public static Result search(String text,String p){if(text==null||p==null)throw new IllegalArgumentException();if(p.isEmpty())return new Result(java.util.stream.IntStream.rangeClosed(0,text.length()).boxed().toList(),0,0);if(p.length()>text.length())return new Result(List.of(),0,0);long mod=1_000_000_007L,base=257,ph=0,th=0,pow=1;for(int i=1;i<p.length();i++)pow=pow*base%mod;for(int i=0;i<p.length();i++){ph=(ph*base+p.charAt(i))%mod;th=(th*base+text.charAt(i))%mod;}List<Integer> out=new ArrayList<>();long hc=0,cc=0;for(int i=0;i<=text.length()-p.length();i++){hc++;if(ph==th){int j=0;while(j<p.length()){cc++;if(text.charAt(i+j)!=p.charAt(j))break;j++;}if(j==p.length())out.add(i);}if(i<text.length()-p.length()){th=(th-text.charAt(i)*pow%mod+mod)%mod;th=(th*base+text.charAt(i+p.length()))%mod;}}return new Result(out,hc,cc);}}
